    dl_LTrazboru2eUzel_push(l, v);
    dt_razboru2eUzel last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(dt_razboru2eUzel));
    l->items[i] = last;
