struct dm_DsDss { dan_hdr h; int64_t len, n, cap, slots; dan_str *keys; dm_Dss* *vals; uint64_t *hashes; bool *alive; int64_t *index; };

static void dm_DsDss_destroy(dan_hdr *h) {
    dm_DsDss *d = (dm_DsDss *)(void *)h;
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) { dan_str_release(d->keys[e]); dm_Dss_release(d->vals[e]); }
    dan_free(d->hashes);
    dan_free(d);
}
static dm_DsDss *dm_DsDss_new(void) {
    dm_DsDss *d = dan_alloc(sizeof *d);
    dan_hdr_new(&d->h, dm_DsDss_destroy);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_DsDss *dm_DsDss_new_detached(void) {
    dm_DsDss *d = dan_alloc(sizeof *d);
    dan_hdr_detached(&d->h);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_DsDss *dm_DsDss_share(dm_DsDss *d) { if (d) dan_hdr_share(&d->h); return d; }
static void dm_DsDss_release(dm_DsDss *d) { if (d) dan_hdr_release(&d->h, dm_DsDss_destroy); }
static void dm_DsDss_give(dm_DsDss *d) { if (d) dan_hdr_give(&d->h, dm_DsDss_destroy); }

/* все части словаря - в одном блоке памяти (одно выделение вместо пяти): отпечатки,
   таблица поиска, ключи, значения и признаки «запись есть» на cap записей */
static void dm_DsDss_block(dm_DsDss *d, int64_t cap) {
    int64_t s = 8;
    while (s < 2 * cap) s *= 2;
    size_t c = (size_t)cap, kb = (sizeof(dan_str) * c + 7) & ~(size_t)7, vb = (sizeof(dm_Dss*) * c + 7) & ~(size_t)7;
    char *b = dan_alloc(8 * c + 8 * (size_t)s + kb + vb + c);
    d->hashes = (uint64_t *)(void *)b;
    d->index = (int64_t *)(void *)(b + 8 * c);
    d->keys = (dan_str *)(void *)(b + 8 * c + 8 * (size_t)s);
    d->vals = (dm_Dss* *)(void *)(b + 8 * c + 8 * (size_t)s + kb);
    d->alive = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb + vb);
    d->cap = cap;
    d->slots = s;
}
static void dm_DsDss_reindex(dm_DsDss *d) {
    int64_t s = d->slots;
    for (int64_t i = 0; i < s; i++) d->index[i] = -1;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        int64_t p = (int64_t)(d->hashes[e] & (uint64_t)(s - 1));
        while (d->index[p] >= 0) p = (p + 1) & (s - 1);
        d->index[p] = e;
    }
}
static int64_t dm_DsDss_lookup(const dm_DsDss *d, dan_str k, uint64_t h) {
    if (!d->slots) return -1;
    for (int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));; p = (p + 1) & (d->slots - 1)) {
        int64_t e = d->index[p];
        if (e < 0) return -1;
        if (d->alive[e] && d->hashes[e] == h) { dan_str a = d->keys[e], b = k; if (dan_str_eq(a, b)) return e; }
    }
}
static void dm_DsDss_grow(dm_DsDss *d) {   /* убирает удалённые записи и увеличивает таблицу */
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dan_str *keys = d->keys; dm_Dss* *vals = d->vals; uint64_t *hashes = d->hashes; bool *alive = d->alive;
    int64_t n = d->n;
    dm_DsDss_block(d, cap);
    for (int64_t e = 0; e < n; e++) {
        if (!alive[e]) continue;
        d->keys[m] = keys[e]; d->vals[m] = vals[e]; d->hashes[m] = hashes[e]; d->alive[m] = true; m++;
    }
    dan_free(hashes);
    d->n = m;
    dm_DsDss_reindex(d);
}
static void dm_DsDss_put(dm_DsDss *d, dan_str k, dm_Dss* v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsDss_lookup(d, k, h);
    if (e >= 0) { dm_Dss* old = d->vals[e]; d->vals[e] = dm_Dss_share(v); dm_Dss_release(old); (void)old; return; }
    if (d->n == d->cap) dm_DsDss_grow(d);
    e = d->n++;
    d->keys[e] = dan_str_share(k); d->vals[e] = dm_Dss_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* запись в новый словарь значений, которые уже учтены (копия для задачи) */
static void dm_DsDss_put_raw(dm_DsDss *d, dan_str k, dm_Dss* v) {
    uint64_t h = dan_hash_s(k);
    if (d->n == d->cap) dm_DsDss_grow(d);
    int64_t e = d->n++;
    d->keys[e] = k; d->vals[e] = v; d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* место значения по ключу; если ключа нет, запись создаётся со значением v (одно обращение
   вместо получить и записать) */
static dm_Dss* *dm_DsDss_slot(dm_DsDss *d, dan_str k, dm_Dss* v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsDss_lookup(d, k, h);
    if (e < 0) {
        if (d->n == d->cap) dm_DsDss_grow(d);
        e = d->n++;
        d->keys[e] = dan_str_share(k); d->vals[e] = dm_Dss_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
        int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
        while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
        d->index[p] = e;
    }
    return &d->vals[e];
}
static dm_DsDss *dm_DsDss_from(int64_t n, const dan_str *ks, const dm_Dss* *vs) {
    dm_DsDss *d = dm_DsDss_new();
    for (int64_t i = 0; i < n; i++) dm_DsDss_put(d, ks[i], vs[i]);
    return d;
}
