#define DAN_W_RUB1 "\321\200\321\203\320\261\320\273\321\214"
#define DAN_W_RUB2 "\321\200\321\203\320\261\320\273\321\217"
#define DAN_W_RUB5 "\321\200\321\203\320\261\320\273\320\265\320\271"
#define DAN_W_KOP1 "\320\272\320\276\320\277\320\265\320\271\320\272\320\260"
